<template>
    <div class="slider-wrap">
        <div ref="container" class="keen-slider">
            <div class="keen-slider__slide number-slide1">
                <img src="../assets/album/party.webp" alt="мастеркласс">
            </div>
            <div class="keen-slider__slide number-slide2">
                <img src="../assets/album/girls.webp" alt="мастера">
            </div>
            <div class="keen-slider__slide number-slide3">
                <img src="../assets/album/toys2.webp" alt="плюшевые игрушки">
            </div>
            <div class="keen-slider__slide number-slide4">
                <img src="../assets/album/christmasTree.webp" alt="ёлочка">
            </div>
            <div class="keen-slider__slide number-slide5">
                <img src="../assets/album/girl.webp" alt="девочка">
            </div>
        </div>
        <div v-if="slider" class="dots">
            <button v-for="(_slide, idx) in dotHelper" @click="slider.moveToIdx(idx)"
                :class="{ dot: true, active: current === idx }" :key="idx"></button>
        </div>
    </div>
</template>


<script>
import 'keen-slider/keen-slider.min.css'
import KeenSlider from 'keen-slider'

export default {
    computed: {
        dotHelper() {
            return this.slider ? [...Array(this.slider.track.details.slides.length).keys()] : []
        },
    },
    data() {
        return {
            current: 1,
            slider: null,
        }
    },
    mounted() {
        this.slider = new KeenSlider(this.$refs.container, {
            loop: true,
            slides: {
                perView: 1.1,
                spacing: 15,
            },
            initial: this.current,
            slideChanged: (s) => {
                this.current = s.track.details.rel
            },
            // + другие опции и плагины
        })
    },
    beforeDestroy() {
        if (this.slider) this.slider.destroy()
    },
}
</script>


<style>
[class^="number-slide"],
[class*=" number-slide"] {
    background: grey;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 50px;
    color: #fff;
    font-weight: 500;
    height: 400px;
}

.slider-wrap {
    display: none;
}

@media (max-width: 1024px) {
    .slider-wrap {
        display: block;
    }
}

.number-slide1 {
    background: rgb(64, 175, 255);
    background: linear-gradient(128deg,
            rgba(64, 175, 255, 1) 0%,
            rgba(63, 97, 255, 1) 100%);
}

.number-slide2 {
    background: rgb(255, 75, 64);
    background: linear-gradient(128deg,
            rgba(255, 154, 63, 1) 0%,
            rgba(255, 75, 64, 1) 100%);
}

.number-slide3 {
    background: rgb(182, 255, 64);
    background: linear-gradient(128deg,
            rgba(182, 255, 64, 1) 0%,
            rgba(63, 255, 71, 1) 100%);
    background: linear-gradient(128deg,
            rgba(189, 255, 83, 1) 0%,
            rgba(43, 250, 82, 1) 100%);
}

.number-slide4 {
    background: rgb(64, 255, 242);
    background: linear-gradient(128deg,
            rgba(64, 255, 242, 1) 0%,
            rgba(63, 188, 255, 1) 100%);
}

.number-slide5 {
    background: rgb(255, 64, 156);
    background: linear-gradient(128deg,
            rgba(255, 64, 156, 1) 0%,
            rgba(255, 63, 63, 1) 100%);
}

.number-slide6 {
    background: rgb(64, 76, 255);
    background: linear-gradient(128deg,
            rgba(64, 76, 255, 1) 0%,
            rgba(174, 63, 255, 1) 100%);
}

.navigation-wrapper {
    position: relative;
}

.slider-wrap {
    position: relative;
}

.dots {
    position: absolute;
    bottom: 0px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    padding: 10px 0;
    justify-content: center;
    z-index: 10;
}

.dot {
    border: none;
    width: 10px;
    height: 10px;
    background: var(--accent-red-light);
    border-radius: 50%;
    margin: 0 5px;
    padding: 5px;
    cursor: pointer;
}

.dot:focus {
    outline: none;
}

.dot.active {
    /* background: #fff; */
    /* background: var(--accent-red-light); */
    background: #fff;
}

.arrow {
    width: 30px;
    height: 30px;
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    -webkit-transform: translateY(-50%);
    fill: #fff;
    cursor: pointer;
}

.arrow--left {
    left: 5px;
}

.arrow--right {
    left: auto;
    right: 5px;
}

.arrow--disabled {
    fill: rgba(255, 255, 255, 0.5);
}
</style>